import { Action, ActionPanel, Color, Icon, List, showHUD, showToast, Toast } from "@raycast/api";
import { exec } from "child_process";
import { promisify } from "util";

const execPromise = promisify(exec);
const CTL_BIN = "/opt/homebrew/bin/omniwmctl";

async function runOmniCommand(cmd: string) {
  try {
    await execPromise(`${CTL_BIN} command ${cmd}`);
    await showHUD(`Executed: ${cmd}`);
  } catch (error: any) {
    await showToast({
      style: Toast.Style.Failure,
      title: "Command failed",
      message: error.message,
    });
  }
}

export default function Command() {
  return (
    <List searchBarPlaceholder="Search settings command...">
      <List.Section title="General Configurations">
        <List.Item
          title="Toggle Animations"
          subtitle="Enable/Disable window animation transitions"
          icon={{ source: Icon.Circle, tintColor: Color.Blue }}
          actions={
            <ActionPanel>
              <Action title="Toggle" onAction={() => runOmniCommand("toggle-animations")} />
            </ActionPanel>
          }
        />
        <List.Item
          title="Toggle Workspace Bar"
          subtitle="Show or hide the bar layout"
          icon={{ source: Icon.Sidebar, tintColor: Color.Green }}
          actions={
            <ActionPanel>
              <Action title="Toggle" onAction={() => runOmniCommand("toggle-workspace-bar")} />
            </ActionPanel>
          }
        />
        <List.Item
          title="Toggle Fullscreen"
          subtitle="Maximize or restore focused window"
          icon={{ source: Icon.Maximize, tintColor: Color.Yellow }}
          actions={
            <ActionPanel>
              <Action title="Toggle" onAction={() => runOmniCommand("toggle-fullscreen")} />
            </ActionPanel>
          }
        />
      </List.Section>
    </List>
  );
}
